def longest_word(words):
    if not words:
        return None
    return max(words, key=len)

def rotate_items(items, k):
    if items is None:
        return None
    if k < 0:
        raise ValueError("k must be nonnegative")
    if not items:
        return ()
    k %= len(items)
    if k == 0:
        return tuple(items)
    return tuple(items[-k:]) + tuple(items[:-k])

def interleave(left, right):
    if len(left) != len(right):
        raise ValueError("left and right must be equally sized")
    if len(left) == 0:
        return None
    result = []
    for left_item, right_item in zip(left, right):
        result.extend((left_item, right_item))
    return tuple(result)

def sort_labels(labels):
    seen = {}
    for label in labels:
        key = label.casefold()
        if key not in seen:
            seen[key] = label
    if not seen:
        return None
    return tuple(seen[key] for key in sorted(seen))

def find_products(products, query):
    if not products:
        return None

    normalized_query = query.casefold()
    matches = [
        product
        for product in products
        if normalized_query in product["name"].casefold()
    ]
    return sorted(matches, key=lambda product: product["score"], reverse=True)

def group_words(words):
    groups = {}
    for word in words:
        key = word[0].casefold()
        groups.setdefault(key, []).append(word)
    if not groups:
        return None
    return tuple((key, tuple(group)) for key, group in groups.items())

def parse_integer_fields(fields):
    if not fields:
        return None
    return tuple(int(field) for field in fields)

def nearest_date(dates, target):
    if not dates:
        return None

    from datetime import date

    target_date = date.fromisoformat(target)
    return min(dates, key=lambda value: abs((date.fromisoformat(value) - target_date).days))

def median_value(values):
    if len(values) == 0:
        return None

    ordered = sorted(values)
    middle = len(ordered) // 2

    if len(ordered) % 2:
        return ordered[middle]

    return (ordered[middle - 1] + ordered[middle]) / 2

def merge_ranges(ranges):
    if not ranges:
        return None

    sorted_ranges = sorted(ranges, key=lambda r: r[0])
    merged = []
    start, end = sorted_ranges[0]

    for current_start, current_end in sorted_ranges[1:]:
        if current_start <= end:
            end = max(end, current_end)
        else:
            merged.append((start, end))
            start, end = current_start, current_end

    merged.append((start, end))
    return merged

def shortest_path(graph, start, goal):
    from collections import deque

    if not graph:
        return None
    if start not in graph or goal not in graph:
        return None
    if start == goal:
        return (start,)

    queue = deque([start])
    parents = {start: None}

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor in parents:
                continue
            parents[neighbor] = node
            if neighbor == goal:
                path = [goal]
                while path[-1] != start:
                    path.append(parents[path[-1]])
                path.reverse()
                return tuple(path)
            queue.append(neighbor)

    return ()

def topological_order(nodes, edges):
    node_list = tuple(nodes)
    node_set = set(node_list)
    adjacency = {node: [] for node in node_list}
    indegree = {node: 0 for node in node_list}

    for source, destination in edges:
        if source not in node_set or destination not in node_set:
            raise ValueError("edge contains a node not present in nodes")
        adjacency[source].append(destination)
        indegree[destination] += 1

    if not node_list:
        return None

    ready = [node for node in node_list if indegree[node] == 0]
    order = []
    index = 0

    while index < len(ready):
        source = ready[index]
        index += 1
        order.append(source)

        for destination in adjacency[source]:
            indegree[destination] -= 1
            if indegree[destination] == 0:
                ready.append(destination)

    if len(order) != len(node_list):
        raise ValueError("graph contains a cycle")

    return tuple(order)
